159	    // A y B con respuesta (tokens 120 y 340, costo 0.001 y 0.003); C: el proveedor no responde (503 en todos los reintentos).
160	    static Fila Guion(string pregunta) => pregunta switch
161	    {
162	        "pregunta-a" => new Fila(200, 100, 20, 0.001, Pedido, [Pedido]),
163	        "pregunta-b" => new Fila(200, 300, 40, 0.003, Pedido, [Pedido]),
164	        "pregunta-c" => new Fila(503, 0, 0, 0, Pedido, []),
165	        _ => new Fila(403, 0, 0, 0, null, []),
166	    };
