172	    [Fact]
173	    public async Task T6g_promedios_del_grupo_resto_solo_sobre_las_que_respondieron_json()
174	    {
175	        var (data, cwd) = Escenario(CasosConSinResultado());
176	        var aud = Path.Combine(NuevoDir(), "auditoria.jsonl");
