178	        var s = await Ejecutar(data, cwd, api.Url, aud);
179	
180	        Assert.Contains("SIN RESULTADO", s.Texto);
181	        var resto = s.Json.GetProperty("modelo").GetProperty("resto");
182	        Assert.Equal(3, resto.GetProperty("preguntas").GetInt32());          // tamaño del grupo
183	        Assert.Equal(2, resto.GetProperty("conRespuesta").GetInt32());
184	        Assert.Equal(1, resto.GetProperty("sinResultado").GetInt32());
185	        Assert.Equal(460, resto.GetProperty("tokens").GetInt64());
186	        Assert.Equal(230, resto.GetProperty("tokensPromedio").GetDouble(), 6);      // 460 / 2, no 460 / 3
187	        Assert.Equal(0.004, resto.GetProperty("costoTotalUsd").GetDouble(), 9);
188	        Assert.Equal(2.0, resto.GetProperty("costoPor1000Usd").GetDouble(), 6);     // 0.004 / 2 * 1000, no / 3
189	
190	        var r = s.Json.GetProperty("resumen");
191	        Assert.Equal(2, r.GetProperty("conRespuesta").GetInt32());
192	        Assert.Equal(3, r.GetProperty("total").GetInt32());
193	        Assert.Equal(1, r.GetProperty("sinResultado").GetInt32());
194	        Assert.Equal(460, r.GetProperty("tokensTotales").GetInt64());
195	        Assert.Equal(230, r.GetProperty("tokensPromedio").GetDouble(), 6);
196	        Assert.Equal(0.002, r.GetProperty("costoPromedioUsd").GetDouble(), 9);
197	        Assert.Equal(2.0, r.GetProperty("costoPor1000Usd").GetDouble(), 6);
198	    }
